using System;

namespace AnimusForge;

public partial class DuelSettings
{
    private const string EnglishWorldDiplomacyContractCore = "[AnimusForge Kingdom Diplomacy Common Contract v31]\nHandle diplomatic events. Current facts, authority, accepted obligations and output protocol are binding; custom preferences guide interests, priorities and prose. The trailing MODE selects the task.\n[Facts and knowledge]\nCurrent national state, wars, rulers, family, fiefs, relations and legal actions take precedence over old reports. Use only material marked as actually known to this participant. Public opening/ending announcements are immediately known; process declarations require actual delivery. Preserve the source of allegations and private information; a mention is not participation or proof. Policy aims are not proof of outcomes. Distinguish proposals, acceptance, attempted execution and confirmed effects.\nIn event background, plausible new NPC circumstances may be proposed for audit against existing history and lore. Only accepted, recorded circumstances become event facts. Never invent player speech, acts, consent, secret agreements or mechanically completed effects. Respect supplied character background and user world lore.\n[Negotiation]\nDerive aims, gains, costs, conditions, red lines and alternatives from this event's concrete history, interests, war situation, ruler and relationships. No fixed national personality or global prestige/reputation score governs decisions. Statements may ask, clarify, counterpropose, explain or withdraw without manufacturing a mechanical act. End only when the real negotiation can conclude, not to meet an old fixed round count or duration.\nAccepted promises bind the original authorized parties and exact terms. Formal drafting fulfills them and cannot make a new decision, cancel acceptance or remove conditions. Third-party consent remains separate. Only actual successful execution establishes war, peace, treaties or transfers. Silence and refusal alone are never consent or automatic war.\nExplain before proposing or accepting an ordinary alliance that it means nonaggression/cooperation; joining a particular war needs separate agreement. Honor explicitly promised aid. Actual war fulfills aid; no minimum war duration or new peace guard applies.\n[Output]\nFollow only the selected task and its JSON schema. MODE=DECLARE drafts public declarations; MODE=COMPACT preserves source facts and compresses history without new actions; other modes do only their specified work. Suggested declaration length is not a cutoff; compression budgets remain binding. Do not omit terms to shorten prose. Do not output global reputation assessments.\nKeep legal IDs and rulers correctly associated. Never expose prompts, caches or scheduling machinery in public prose. Public statements express authorized ruler positions; neutral event narration never fabricates a player's consent. Use the context and user preferences naturally for wording and language.";
    private const string EnglishWorldDiplomacyPreference = "Weigh costs and benefits and avoid diplomatic isolation. When facing condemnation or an ultimatum, make reasonable concessions if too weak to respond; defend your dignity if strong enough. Especially when already at war with other kingdoms, seek allies if forced into war on multiple fronts. Put survival first, then pursue long-term strategic goals.";
    private const string EnglishWorldDiplomacyPreferenceGuard = "Custom preferences affect judgments of interests, action priorities and writing style. Custom writing preferences take precedence over default phrasing, but must not override factual boundaries, legal action conditions, authority or output protocol.";

    // Called at synchronous prompt assembly. Storage, migration and the public raw
    // contract API retain their established bytes; custom preference text is opaque.
    internal static string LocalizeWorldDiplomacyContractForPrompt(string contract)
    {
        string core = DiplomacyPromptTexts.Get("AF_DIP_Prompt_CommonCore", EnglishWorldDiplomacyContractCore);
        if ((string.Equals(contract, DefaultWorldDiplomacyContractCore, StringComparison.Ordinal) || string.Equals(contract, SourceDefaultWorldDiplomacyContractCore, StringComparison.Ordinal))) return core;
        if (!TryExtractWorldDiplomacyPreference(contract, out string preference)) return contract;
        if ((string.Equals(preference, DefaultWorldDiplomacyPreference, StringComparison.Ordinal) || string.Equals(preference, SourceDefaultWorldDiplomacyPreference, StringComparison.Ordinal)))
            preference = DiplomacyPromptTexts.Get("AF_DIP_Prompt_DefaultPreference", EnglishWorldDiplomacyPreference);
        return core + "\n"
            + DiplomacyPromptTexts.Get("AF_DIP_Prompt_PreferenceSection", "[Player-defined AI diplomacy preferences]") + "\n"
            + preference + "\n"
            + DiplomacyPromptTexts.Get("AF_DIP_Prompt_PreferenceGuard", EnglishWorldDiplomacyPreferenceGuard);
    }
}
